+/**
+ * Swan Flight Lab — shared, deterministic, cycle-averaged benchmark.
+ * SI units; x forward, y up, z lateral. No rendering or DOM dependencies.
+ * Historical geometry is not evidence for the assumed aerodynamic model.
+ */
+const FT = 0.3048;
+const IN = 0.0254;
+const span = 7.4 * FT;
+const area = 6.61 * FT * FT;
+export const parameters = Object.freeze({
+  span_m: span,
+  wing_area_m2: area,
+  wrist_span_m: 3.7 * FT,
+  shoulder_span_m: 4 * IN,
+  body_width_m: 8 * IN,
+  overall_length_m: 55 * IN,
+  aspect_ratio: span * span / area
+});
+export const constants = Object.freeze({
+  mass_kg: 6, g: 9.80665, rho: 1.225, ground_m: 0.2,
+  mechanical_power_w: 400, efficiency: 0.65, frequency_hz: 2
+});
+const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
+const dot = (a, b) => a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
+const cross = (a,b) => [
+  a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]
+];
+const unit = a => {
+  const n = Math.hypot(...a);
+  return n > 1e-12 ? a.map(v => v/n) : [1,0,0];
+};
+function controlValues(c = {}) {
+  return {
+    throttle: clamp(c.throttle ?? 0, 0, 1),
+    pitch: clamp(c.pitch ?? 0, -1, 1),
+    bank: clamp(c.bank ?? 0, -1, 1),
+    brake: clamp(c.brake ?? 0, 0, 1)
+  };
+}
+export function forces(state, controls = {}, environment = {}) {
+  const c = controlValues(controls);
+  const wind = environment.wind ?? [0,0,0];
+  const rho = environment.rho ?? constants.rho;
+  const air = state.velocity.map((v,i) => v - wind[i]);
+  const airspeed = Math.hypot(...air);
+  const forward = airspeed > 1e-12 ? air.map(v => v/airspeed) : [1,0,0];
+  const alpha = state.pitch - Math.atan2(air[1], Math.hypot(air[0], air[2]));
+  const cl = clamp(0.6 + 3*alpha, -0.2, 1.4);
+  const cd = 0.035 + cl*cl/(Math.PI*0.8*parameters.aspect_ratio);
+  const qS = 0.5*rho*airspeed*airspeed*parameters.wing_area_m2;
+  const lift = qS*cl;
+  const drag = qS*cd;
+  const power = constants.mechanical_power_w*c.throttle;
+  const thrust = constants.efficiency*power/Math.max(airspeed, 5);
+  let up = [-forward[0]*forward[1], 1-forward[1]*forward[1], -forward[2]*forward[1]];
+  if (Math.hypot(...up) < 1e-9) {
+    // At vertical flow world-up has no projection: choose a finite perpendicular.
+    const reference = [1,0,0];
+    const d = dot(reference, forward);
+    up = reference.map((v,i) => v-d*forward[i]);
+  }
+  up = unit(up);
+  const perpendicular = cross(forward, up);
+  const liftDirection = up.map((v,i) =>
+    v*Math.cos(state.roll) + perpendicular[i]*Math.sin(state.roll)
+  );
+  const force = forward.map((v,i) => (thrust-drag)*v + lift*liftDirection[i]);
+  force[1] -= constants.mass_kg*constants.g;
+  if (state.position[1] <= constants.ground_m + 1e-10 && state.velocity[1] <= 0) {
+    force[1] = Math.max(0, force[1]); // Unilateral normal reaction, not altitude lock.
+    const horizontal = Math.hypot(state.velocity[0], state.velocity[2]);
+    if (horizontal > 1e-12 && c.brake > 0) {
+      force[0] -= 18*c.brake*state.velocity[0]/horizontal;
+      force[2] -= 18*c.brake*state.velocity[2]/horizontal;
+    }
+  }
+  return {lift, drag, thrust, power, airspeed, cl, force};
+}
+export function step(state, controls = {}, environment = {}, dt) {
+  if (!Number.isFinite(dt) || dt <= 0 || dt > 0.05) {
+    throw new RangeError('dt must be finite and in (0, 0.05] seconds');
+  }
+  const c = controlValues(controls);
+  const next = {
+    ...state, position: [...state.position], velocity: [...state.velocity],
+    time: state.time + dt,
+    phase: state.phase + (c.throttle > 0 ? 2*Math.PI*constants.frequency_hz*dt : 0)
+  };
+  // A crash is terminal until a preset is loaded.
+  if (state.status === 'crashed') {
+    next.position[1] = Math.max(constants.ground_m, next.position[1]);
+    next.velocity = [0,0,0];
+    return next;
+  }
+  const f = forces(state, c, environment).force; // Current attitude, before control rates.
+  next.velocity = state.velocity.map((v,i) => v + f[i]*dt/constants.mass_kg);
+  const onGround = state.position[1] <= constants.ground_m + 1e-10 && state.velocity[1] <= 0;
+  if (onGround && c.brake > 0) {
+    // A discrete braking impulse must never reverse horizontal motion.
+    const oldHorizontal = Math.hypot(state.velocity[0], state.velocity[2]);
+    if (oldHorizontal > 0 &&
+        next.velocity[0]*state.velocity[0] + next.velocity[2]*state.velocity[2] < 0) {
+      next.velocity[0] = 0;
+      next.velocity[2] = 0;
+    }
+  }
+  next.position = state.position.map((v,i) => v + next.velocity[i]*dt);
+  next.pitch = clamp(state.pitch + 0.5*c.pitch*dt, -0.35, 0.45);
+  const rollTarget = 0.6*c.bank;
+  next.roll = state.roll + clamp(rollTarget-state.roll, -2*dt, 2*dt);
+  if (next.position[1] <= constants.ground_m) {
+    const touchingDown = state.status === 'flying' || state.position[1] > constants.ground_m + 1e-10;
+    next.position[1] = constants.ground_m;
+    if (touchingDown) {
+      const sink = Math.max(0, -next.velocity[1]);
+      const horizontal = Math.hypot(next.velocity[0], next.velocity[2]);
+      const safe = sink <= 3 && horizontal <= 14 && Math.abs(next.roll) <= 0.35;
+      next.status = safe ? 'landed' : 'crashed';
+      if (!safe) next.velocity = [0,0,0];
+    } else {
+      next.status = state.status === 'landed' ? 'landed' : 'grounded';
+    }
+    next.velocity[1] = Math.max(0, next.velocity[1]);
+  } else {
+    next.status = 'flying';
+  }
+  return next;
+}

